CREATE     PROCEDURE [synapse_fo].[usp_Insert_MAINACCOUNT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:54
	Description: Insert stored procedure for MAINACCOUNT from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[MAINACCOUNT]
	(
		[ACCOUNTCATEGORYREF],
		[ADJUSTMENTMETHOD_MX],
		[CLOSETYPE],
		[CLOSING],
		[CONSOLIDATIONMAINACCOUNT],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CURRENCYCODE],
		[DataLakeModified_DateTime],
		[DEBITCREDITBALANCEDEMAND],
		[DEBITCREDITCHECK],
		[DEBITCREDITPROPOSAL],
		[EXCHANGEADJUSTED],
		[EXCHANGEADJUSTMENTRATETYPE],
		--[FileName],
		[FINANCIALREPORTINGEXCHANGERATETYPE],
		[FINANCIALREPORTINGTRANSLATIONTYPE],
		[INFLATIONADJUSTMENT_MX],
		[LastProcessedChange_DateTime],
		[LEDGERCHARTOFACCOUNTS],
		--[LSN],
		[MAINACCOUNTID],
		[MAINACCOUNTTEMPLATE],
		[MANDATORYPAYMENTREFERENCE],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[MONETARY],
		[NAME],
		[OFFSETLEDGERDIMENSION],
		[OPENINGACCOUNT],
		[PARENTMAINACCOUNT],
		[PARTITION],
		[POSTINGTYPE],
		[RECID],
		[RECVERSION],
		[REPOMOTYPE_MX],
		[REPORTINGACCOUNTTYPE],
		[REPORTINGEXCHANGEADJUSTMENTRATETYPE],
		[SRUCODE],
		[STANDARDMAINACCOUNT_W],
		--[SysRowId],
		[TRANSFERYEARENDACCOUNT_ES],
		[TYPE],
		[UNITOFMEASURE],
		[USERINFOID],
		[VALIDATECURRENCY],
		[VALIDATEPOSTING],
		[VALIDATEUSER]
	)
	SELECT 
		stg.[ACCOUNTCATEGORYREF],
		stg.[ADJUSTMENTMETHOD_MX],
		stg.[CLOSETYPE],
		stg.[CLOSING],
		stg.[CONSOLIDATIONMAINACCOUNT],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CURRENCYCODE],
		stg.[DataLakeModified_DateTime],
		stg.[DEBITCREDITBALANCEDEMAND],
		stg.[DEBITCREDITCHECK],
		stg.[DEBITCREDITPROPOSAL],
		stg.[EXCHANGEADJUSTED],
		stg.[EXCHANGEADJUSTMENTRATETYPE],
		--stg.--[FileName],
		stg.[FINANCIALREPORTINGEXCHANGERATETYPE],
		stg.[FINANCIALREPORTINGTRANSLATIONTYPE],
		stg.[INFLATIONADJUSTMENT_MX],
		stg.[LastProcessedChange_DateTime],
		stg.[LEDGERCHARTOFACCOUNTS],
		--stg.--[LSN],
		stg.[MAINACCOUNTID],
		stg.[MAINACCOUNTTEMPLATE],
		stg.[MANDATORYPAYMENTREFERENCE],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[MONETARY],
		stg.[NAME],
		stg.[OFFSETLEDGERDIMENSION],
		stg.[OPENINGACCOUNT],
		stg.[PARENTMAINACCOUNT],
		stg.[PARTITION],
		stg.[POSTINGTYPE],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REPOMOTYPE_MX],
		stg.[REPORTINGACCOUNTTYPE],
		stg.[REPORTINGEXCHANGEADJUSTMENTRATETYPE],
		stg.[SRUCODE],
		stg.[STANDARDMAINACCOUNT_W],
		--stg.--[SysRowId],
		stg.[TRANSFERYEARENDACCOUNT_ES],
		stg.[TYPE],
		stg.[UNITOFMEASURE],
		stg.[USERINFOID],
		stg.[VALIDATECURRENCY],
		stg.[VALIDATEPOSTING],
		stg.[VALIDATEUSER]	
	FROM [staging_fo].[MAINACCOUNT] stg
		LEFT JOIN [synapse_fo].[MAINACCOUNT] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
